def safe_divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return "Деление на ноль невозможно!"

print(safe_divide(10, 2))  # 5.0
print(safe_divide(10, 0))  # Деление на ноль невозможно!

def get_number():
    while True:
        try:
            val = int(input("Введите целое число: "))
            return val
        except ValueError:
            print("Это не целое число, попробуйте ещё раз!")

